/* Œconomia — Entraînement : thème « État et biens publics » (36 exercices, trois niveaux). */
(function () {
  const X = OEC.exo, { rnd, pick, fmt } = X;
  const P = (...a) => a.map((t) => `<p>${t}</p>`).join("");

  /* Marché avec externalité : demande P = a − Q, coût marginal privé = c + Q, coût externe e par unité */
  const genExt = () => { const e = pick([6, 10, 12, 14]); const Qs = rnd(15, 40); const c = rnd(5, 20); return { a: c + 2 * Qs, c, e, Qm: Qs }; };

  X.theme({ id: "etat", nom: "État et biens publics",
    intro: "Pourquoi l’État intervient-il dans l’économie, comment finance-t-il ses dépenses, et quelles sont les limites de son action ? Ces exercices vous entraînent à reconnaître les défaillances du marché, à calculer des soldes budgétaires, des multiplicateurs et des taxes correctrices, et à débattre du rôle de l’État.",
    notions: ["bien-public", "externalite", "biens-communs", "choix-public", "asymetrie-information", "multiplicateur", "equivalence-ricardienne"] });

  X.add([
  /* =========================== NIVEAU 1 : DÉCOUVERTE =========================== */
  { id: "et1-bien-public", theme: "etat", niveau: 1, type: "qcm", notion: "bien-public",
    titre: "Reconnaître un bien public", competence: "Identifier un bien non rival et non excluable.",
    enonce: P("Lequel de ces biens est un bien public au sens économique ?"),
    options: ["Une baguette de pain.", "L’éclairage public d’une rue.", "Un abonnement à une plateforme de streaming.", "Un appartement en location."], c: 1, pourquoi: ["La baguette est rivale (si je la mange, vous ne pouvez plus) et excluable (il faut la payer) : c’est un bien privé.", null, "L’abonnement est excluable : sans payer, pas d’accès. C’est un bien de club.", "L’appartement est rival et excluable : un seul ménage peut l’occuper, contre un loyer."],
    explication: P("Un <b>bien public</b> a deux caractéristiques : il est <b>non rival</b> (le fait que je l’utilise n’empêche pas les autres de l’utiliser) et <b>non excluable</b> (on ne peut pas empêcher quelqu’un d’en profiter). L’éclairage public profite à tous les passants, sans qu’on puisse faire payer chacun.", "Le marché le fournit mal, car chacun a intérêt à en profiter sans payer : c’est le problème du <b>passager clandestin</b>. D’où son financement par l’impôt.") },

  { id: "et1-vf-biens", theme: "etat", niveau: 1, type: "vf", notion: "biens-communs",
    titre: "Quatre types de biens", competence: "Classer des biens selon la rivalité et l’exclusion.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Les poissons d’un lac ouvert à tous les pêcheurs sont un bien commun : rivaux mais non excluables.", true, "Ce que pêche l’un manque aux autres, et il est difficile d’exclure qui que ce soit : c’est le cadre de la « tragédie des communs », étudiée par Hardin et Ostrom."],
      ["La défense nationale d’un pays est un bien privé : rivale et excluable.", false, "C’est un exemple classique de <b>bien public</b> : elle protège tous les habitants à la fois, et on ne peut pas en exclure ceux qui ne paient pas."],
      ["Un film diffusé sur une plateforme payante est un bien de club : non rival mais excluable.", true, "Le regarder n’empêche pas les autres de le voir, mais seuls les abonnés y ont accès."],
      ["Un phare qui guide tous les navires d’un port est un bien public : non rival et non excluable.", true, "Un navire de plus qui profite du signal n’empêche pas les autres d’en profiter, et on ne peut pas exclure ceux qui ne paient pas."]
    ] },

  { id: "et1-depenses", theme: "etat", niveau: 1, type: "calcul", notion: "bien-public",
    titre: "Le poids des dépenses publiques", competence: "Calculer une part de dépenses publiques dans le PIB.",
    gen: () => ({ d: rnd(240, 300), y: rnd(780, 880) }),
    enonce: (p) => P(`Les dépenses de l’ensemble des administrations publiques d’un pays (État central, régions, communes et assurances sociales) s’élèvent à <b>${p.d} milliards</b> de francs, pour un PIB de <b>${p.y} milliards</b>.`, "Quelle est la part des dépenses publiques dans le PIB ? Arrondissez à une décimale."),
    champs: [{ label: "Dépenses publiques", unite: "% du PIB", tol: 0.1 }],
    reponses: (p) => [Math.round((p.d / p.y) * 1000) / 10],
    indice: "Part = dépenses publiques ÷ PIB × 100.",
    correction: (p) => P(`Part = ${p.d} ÷ ${p.y} × 100`, `≈ <b>${fmt(100 * p.d / p.y, 1)} %</b> du PIB.`, "Cet ordre de grandeur, environ un tiers, correspond à celui de la Suisse, nettement en dessous de la moyenne de l’Union européenne, proche de la moitié. Attention : une grande partie de ces dépenses sont des transferts (retraites, allocations), qui ne sont pas une production de l’État mais une redistribution.") },

  { id: "et1-externalite", theme: "etat", niveau: 1, type: "qcm", notion: "externalite",
    titre: "Une externalité négative", competence: "Reconnaître une externalité et la réponse proposée par Pigou.",
    enonce: P("Une usine rejette des fumées qui salissent le linge et nuisent à la santé des habitants voisins, sans les indemniser. Quelle réponse l’économiste Arthur Pigou proposait-il ?"),
    options: ["Laisser faire : le marché corrigera seul le problème, grâce aux plaintes des voisins.", "Taxer chaque unité produite d’un montant égal au dommage causé aux voisins.", "Subventionner l’usine pour qu’elle produise davantage et baisse ses prix.", "Interdire toute production industrielle dans la région, pour supprimer la pollution."], c: 1, pourquoi: ["Sans intervention, l’usine n’a aucune raison de tenir compte d’un dommage qu’elle ne paie pas : c’est le sens même d’une externalité.", null, "Une subvention ferait produire davantage, donc polluer davantage : c’est l’inverse de ce qu’il faut.", "Pigou ne veut pas supprimer la production, mais la ramener au niveau où ses avantages couvrent tous ses coûts, dommages compris."],
    explication: P("Les fumées sont une <b>externalité négative</b> : un coût imposé à des tiers, qui n’apparaît pas dans le prix. L’usine produit donc trop, du point de vue de la société.", "Pigou propose en 1920 une <b>taxe</b> égale au dommage marginal : l’entreprise « internalise » le coût et réduit sa production jusqu’au niveau socialement souhaitable. La taxe CO2 sur les combustibles en Suisse repose sur cette idée.") },

  { id: "et1-solde", theme: "etat", niveau: 1, type: "calcul",
    titre: "Déficit et dette", competence: "Calculer un solde budgétaire et l’évolution de la dette.",
    gen: () => ({ r: rnd(70, 90), d: rnd(72, 95), dette: rnd(100, 160) }),
    enonce: (p) => P(`Cette année, un État a perçu <b>${p.r} milliards</b> de recettes et dépensé <b>${p.d} milliards</b>. Sa dette au début de l’année était de <b>${p.dette} milliards</b>.`, "Calculez le solde budgétaire (signe moins en cas de déficit), puis la dette en fin d’année. On suppose que tout déficit est financé par l’emprunt et que tout excédent rembourse la dette."),
    champs: [{ label: "Solde", unite: "milliards", tol: 0.05 }, { label: "Dette en fin d’année", unite: "milliards", tol: 0.05 }],
    reponses: (p) => [p.r - p.d, p.dette - (p.r - p.d)],
    indice: "Solde = recettes − dépenses. Nouvelle dette = ancienne dette − solde (un déficit l’augmente).",
    correction: (p) => { const s = p.r - p.d, nd = p.dette - s; return P(`Solde = ${p.r} − ${p.d} = <b>${s} milliards</b> : ${s < 0 ? "un déficit" : s > 0 ? "un excédent" : "un équilibre"}.`, `Dette en fin d’année = ${p.dette} ${s < 0 ? "+ " + (-s) : "− " + s} = <b>${nd} milliards</b>.`, "Le <b>déficit</b> est un flux (ce qui manque une année) ; la <b>dette</b> est un stock (l’accumulation des déficits passés). Les deux sont souvent confondus dans le débat public."); } },

  { id: "et1-smith", theme: "etat", niveau: 1, type: "qcm", notion: "bien-public",
    titre: "Les devoirs du souverain selon Adam Smith", competence: "Connaître la vision classique du rôle de l’État.",
    enonce: P("Dans La Richesse des nations (1776), Adam Smith, partisan de la liberté économique, assigne pourtant des devoirs à l’État. Lesquels ?"),
    options: ["Fixer les prix des biens de première nécessité et les salaires, pour protéger les plus pauvres.", "Aucun, car pour lui la main invisible suffit et l’État n’a pas de rôle économique.", "Diriger les grandes manufactures et le commerce extérieur, pour accumuler des métaux précieux.", "Assurer la défense, la justice et les ouvrages publics qu’aucun intérêt privé ne financerait, comme les routes."], c: 3, pourquoi: ["Smith critique les règlements qui fixent prix et salaires : pour lui, ce rôle revient au marché.", "Smith n’est pas anarchiste : il assigne au souverain trois devoirs précis.", "C’est la politique des mercantilistes, que Smith combat. Il ne confie à l’État que ce qu’aucun intérêt privé ne financerait.", null],
    explication: P("Smith défend le marché, mais il assigne au souverain trois devoirs : protéger la société contre les agressions extérieures (<b>défense</b>), protéger chacun contre l’injustice des autres (<b>justice</b>), et financer les <b>ouvrages publics</b> utiles à tous mais non rentables pour un particulier, comme les routes, les ponts ou l’éducation de base.", "On reconnaît déjà l’idée de bien public, formalisée par Samuelson en 1954.") },

  { id: "et1-frein", theme: "etat", niveau: 1, type: "qcm",
    titre: "Le frein à l’endettement", competence: "Comprendre une règle budgétaire suisse.",
    enonce: P("En 2001, 85 % des votants suisses ont accepté le « frein à l’endettement », appliqué à la Confédération depuis 2003. Que prévoit-il ?"),
    options: ["Le budget doit être équilibré chaque année, quelle que soit la conjoncture.","Le budget doit être équilibré sur l’ensemble du cycle conjoncturel.","La dette fédérale ne doit pas dépasser 60 % du PIB, comme dans l’Union européenne.","Toute dépense nouvelle doit être approuvée en votation populaire."], c: 1, pourquoi: ["Le frein n’interdit pas tout déficit : il en autorise en période de faible conjoncture, compensés plus tard par des excédents.", null, "Le seuil de 60 % est un critère européen. Le frein suisse ne fixe pas de plafond de dette, il lie les dépenses aux recettes sur le cycle conjoncturel.", "Le frein est une règle de calcul du plafond de dépenses, appliquée par le Conseil fédéral et le Parlement. Il ne prévoit pas de vote populaire sur chaque dépense."],
    explication: P("Le frein à l’endettement plafonne les dépenses en fonction des recettes, corrigées de la conjoncture : en période de ralentissement, les recettes baissent et un déficit est autorisé ; en période de forte conjoncture, un excédent est exigé. Le budget doit être équilibré <b>sur le cycle</b>, ce qui laisse jouer les stabilisateurs automatiques.", "Des exceptions sont possibles en cas de situation extraordinaire, comme pendant la pandémie de 2020. La dette de la Confédération a nettement reculé entre 2003 et 2019, avant de remonter avec les dépenses extraordinaires de la pandémie. Rapportée au PIB, elle reste plus basse qu’en 2003.") },

  { id: "et1-budget", theme: "etat", niveau: 1, type: "document", notion: "bien-public",
    titre: "Lire le budget d’une commune", competence: "Lire la répartition d’un budget public.",
    enonce: P("Répartition des dépenses d’une commune fictive de 12 000 habitants (budget total : 60 millions de francs) :") +
      `<table><thead><tr><th>Domaine</th><th>Part</th></tr></thead><tbody><tr><td>Formation (écoles)</td><td>32 %</td></tr><tr><td>Social et santé</td><td>24 %</td></tr><tr><td>Transports et routes</td><td>12 %</td></tr><tr><td>Administration</td><td>10 %</td></tr><tr><td>Sécurité (police, pompiers)</td><td>8 %</td></tr><tr><td>Culture, sport, loisirs</td><td>6 %</td></tr><tr><td>Environnement et aménagement</td><td>8 %</td></tr></tbody></table>` +
      P("Quelle affirmation est correcte ?"),
    options: ["La commune dépense davantage pour l’administration que pour les écoles et la formation.","Les écoles représentent environ 19,2 millions de francs, soit 1 600 francs par habitant.","La culture et le sport représentent la plus grande part du budget de la commune.","Le budget social de la commune est supérieur à 20 millions de francs."], c: 1, pourquoi: ["L’administration représente 10 % du budget, la formation 32 % : les écoles coûtent environ trois fois plus.", null, "La culture et le sport (6 %) sont parmi les plus petits postes ; la formation (32 %) est le premier.", "Le social et la santé représentent 24 % de 60 millions, soit 14,4 millions : moins de 20 millions."],
    explication: P("32 % de 60 millions = <b>19,2 millions</b> de francs, soit 19 200 000 ÷ 12 000 = <b>1 600 francs par habitant</b>. La formation est le premier poste de la commune, devant le social et la santé (24 % × 60 = 14,4 millions).", "En Suisse, l’école obligatoire est principalement financée par les cantons et les communes, ce qui explique son poids important dans leurs budgets.") },

  /* =========================== NIVEAU 2 : INTERMÉDIAIRE =========================== */
  { id: "et2-pigou", theme: "etat", niveau: 2, type: "calcul", notion: "externalite",
    titre: "La taxe pigouvienne", competence: "Calculer la quantité de marché et la quantité optimale en présence d’une externalité.",
    gen: genExt,
    enonce: (p) => P(`Sur un marché, la demande est <b>P = ${p.a} − Q</b> et le coût marginal privé des producteurs est <b>Cm = ${p.c} + Q</b>. Chaque unité produite cause en plus un dommage de <b>${p.e} francs</b> à des tiers (pollution).`, "Calculez la quantité échangée sans intervention (prix = coût marginal privé), puis la quantité socialement optimale (prix = coût marginal privé + dommage)."),
    champs: [{ label: "Quantité de marché", unite: "unités", tol: 0.05 }, { label: "Quantité optimale", unite: "unités", tol: 0.05 }],
    reponses: (p) => [p.Qm, p.Qm - p.e / 2],
    indice: "Marché : a − Q = c + Q. Optimum : a − Q = c + Q + e.",
    correction: (p) => P(`Sans intervention : ${p.a} − Q = ${p.c} + Q, donc 2Q = ${p.a - p.c} et Q = <b>${p.Qm}</b>.`, `Optimum social : ${p.a} − Q = ${p.c} + Q + ${p.e}, donc 2Q = ${p.a - p.c - p.e} et Q = <b>${fmt(p.Qm - p.e / 2)}</b>.`, `Le marché produit ${fmt(p.e / 2)} unités de trop. Une <b>taxe de ${p.e} francs par unité</b>, égale au dommage, ramène la production à l’optimum : c’est la taxe pigouvienne.`) },

  { id: "et2-multiplicateur", theme: "etat", niveau: 2, type: "calcul", notion: "multiplicateur",
    titre: "Le multiplicateur keynésien", competence: "Calculer l’effet d’une dépense publique sur le revenu.",
    gen: () => ({ c: pick([0.5, 0.6, 0.75, 0.8, 0.9]), g: pick([2, 4, 5, 10]) }),
    enonce: (p) => P(`Dans une économie fermée et sans impôt, les ménages consomment <b>${fmt(p.c * 100)} %</b> de chaque franc de revenu supplémentaire (propension marginale à consommer c = ${fmt(p.c, 2)}).`, `L’État augmente ses dépenses de <b>${p.g} milliards</b> de francs. Calculez le multiplicateur, puis la hausse du revenu national.`),
    champs: [{ label: "Multiplicateur", unite: "", tol: 0.01 }, { label: "Hausse du revenu", unite: "milliards", tol: 0.05 }],
    reponses: (p) => [Math.round((1 / (1 - p.c)) * 100) / 100, Math.round((p.g / (1 - p.c)) * 100) / 100],
    indice: "Multiplicateur = 1 ÷ (1 − c).",
    correction: (p) => { const k = 1 / (1 - p.c); return P(`Multiplicateur = 1 ÷ (1 − ${fmt(p.c, 2)}) = <b>${fmt(k, 2)}</b>.`, `Hausse du revenu = ${fmt(k, 2)} × ${p.g} = <b>${fmt(k * p.g, 2)} milliards</b>.`, `La dépense initiale devient un revenu pour des ménages, qui en consomment ${fmt(p.c * 100)} %, ce qui crée un nouveau revenu, et ainsi de suite. Dans la réalité, les impôts, les importations et l’épargne réduisent cet effet. Les estimations vont d’environ 0,5 à plus de 1,5 selon les pays et les circonstances. Elles sont plus élevées en récession et quand la banque centrale ne relève pas ses taux, plus faibles dans une petite économie ouverte. Les économistes proches de Robert Barro les jugent voisines de zéro en temps normal, parce que la dépense publique évince une partie de la dépense privée.`); } },

  { id: "et2-passager", theme: "etat", niveau: 2, type: "qcm", notion: "bien-public",
    titre: "Le passager clandestin", competence: "Expliquer pourquoi le marché fournit mal les biens publics.",
    enonce: P("Les habitants d’un quartier voudraient tous une digue contre les crues. Une entreprise propose de la construire si chacun verse volontairement 500 francs. Pourquoi le projet risque-t-il d’échouer ?"),
    options: ["Parce que la digue est un bien rival, dont l’usage par l’un réduit celui des autres.", "Parce que chacun espère profiter de la digue sans payer, la protection étant ouverte à tous.", "Parce que les entreprises privées ne savent pas construire de digues assez solides.", "Parce que les habitants jugent la protection trop chère et préfèrent s’en passer."], c: 1, pourquoi: ["Une digue n’est pas rivale : protéger une maison de plus ne réduit pas la protection des autres.", null, "Les entreprises savent construire des digues : le problème est de financer le projet, pas de le réaliser.", "L’énoncé dit que tous veulent la digue : le problème vient de l’intérêt de chacun à laisser les autres payer."],
    explication: P("La digue protège tout le quartier, que l’on ait payé ou non : elle est <b>non excluable</b>. Chaque habitant a donc intérêt à laisser les autres payer : c’est le comportement de <b>passager clandestin</b>. Si beaucoup raisonnent ainsi, la digue n’est pas construite, alors que tout le monde la voulait.", "D’où le recours à l’impôt, obligatoire, ou à une organisation collective capable de faire contribuer chacun, comme les anciennes corporations de digues ou de bisses.") },

  { id: "et2-vf-choix-public", theme: "etat", niveau: 2, type: "vf", notion: "choix-public",
    titre: "Les défaillances de l’État", competence: "Connaître les apports de la théorie des choix publics.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["La théorie des choix publics applique aux élus et aux fonctionnaires l’hypothèse qu’ils poursuivent aussi leur intérêt personnel.", true, "C’est l’apport de James Buchanan, Nobel 1986 : l’État n’est pas un planificateur bienveillant, il est fait de personnes avec leurs propres objectifs."],
      ["Un petit groupe très concerné peut obtenir un avantage payé par une majorité peu concernée.", true, "Le gain est concentré sur quelques-uns, le coût dilué sur tous : le groupe a beaucoup plus intérêt à s’organiser que la majorité (Mancur Olson)."],
      ["Selon Hayek, un planificateur central peut rassembler toute l’information nécessaire pour diriger l’économie.", false, "Pour Hayek, la connaissance est dispersée entre des millions de personnes et ne peut pas être centralisée ; les prix de marché la transmettent."],
      ["Selon George Stigler, les autorités de régulation servent en général l’intérêt des consommateurs contre celui des entreprises régulées.", false, "Stigler a montré le risque de « capture » : les régulateurs finissent parfois par servir les intérêts des entreprises régulées."]
    ] },

  { id: "et2-dette-dyn", theme: "etat", niveau: 2, type: "calcul",
    titre: "La dynamique de la dette publique", competence: "Calculer l’évolution du ratio dette/PIB.",
    gen: () => { let p; do { p = { d: pick([30, 60, 90, 120]), r: pick([1, 2, 3, 4]), g: pick([1, 2, 3, 4]), sp: pick([-2, -1, 0, 1, 2]) }; } while (p.r === p.g); return p; },
    enonce: (p) => P(`La dette publique d’un pays représente <b>${p.d} %</b> du PIB. Le taux d’intérêt moyen sur la dette est de <b>${p.r} %</b>, la croissance du PIB nominal de <b>${p.g} %</b>, et le solde primaire (recettes − dépenses hors intérêts) est de <b>${fmt(p.sp)} %</b> du PIB.`, "Le ratio de l’année suivante se calcule par : <b>d′ = d × (1 + r) ÷ (1 + g) − solde primaire</b>. Calculez-le (arrondi à une décimale). Déterminez ensuite le solde primaire, en % du PIB (arrondi à deux décimales, signe moins s’il est négatif), qui laisserait le ratio inchangé, et dites si le solde actuel est supérieur ou inférieur à ce niveau."),
    champs: [{ label: "Dette / PIB", unite: "%", tol: 0.1 }, { label: "Solde primaire stabilisant", unite: "% du PIB", tol: 0.02 }, { label: "Le solde primaire actuel est", choix: ["supérieur au solde stabilisant", "inférieur au solde stabilisant"] }],
    reponses: (p) => [X.arr(p.d * (1 + p.r / 100) / (1 + p.g / 100) - p.sp, 1), X.arr(p.d * (p.r - p.g) / (100 + p.g), 2), p.sp > p.d * (p.r - p.g) / (100 + p.g) ? 0 : 1],
    indice: "Appliquez la formule en exprimant r et g en fraction (3 % = 0,03). Pour le solde stabilisant, écrivez que d′ est égal à d et résolvez pour le solde primaire.",
    correction: (p) => { const v = p.d * (1 + p.r / 100) / (1 + p.g / 100) - p.sp, st = p.d * (p.r - p.g) / (100 + p.g); return P(`d′ = ${p.d} × ${fmt(1 + p.r / 100, 2)} ÷ ${fmt(1 + p.g / 100, 2)} − (${fmt(p.sp)}) ≈ <b>${fmt(v, 1)} %</b> du PIB.`, `Pour que d′ = d, il faut d × (1 + r) ÷ (1 + g) − solde = d, donc solde = d × [(1 + r) ÷ (1 + g) − 1] = d × (r − g) ÷ (1 + g). Avec r et g exprimés en %, le dénominateur devient 100 + g : solde = ${p.d} × (${p.r} − ${p.g}) ÷ ${100 + p.g} ≈ <b>${fmt(st, 2)} % du PIB</b>.`, p.sp > st ? `Le solde actuel (${fmt(p.sp)} %) est <b>supérieur au solde stabilisant</b> : le ratio baisse.` : `Le solde actuel (${fmt(p.sp)} %) est <b>inférieur au solde stabilisant</b> : le ratio monte.`, p.r > p.g ? "Quand le taux d’intérêt dépasse la croissance, la dette tend à augmenter d’elle-même, sauf si l’État dégage un excédent primaire suffisant." : "Quand la croissance dépasse le taux d’intérêt, le ratio tend à baisser même avec un léger déficit primaire : c’est ce qui a permis, avec l’inflation et des taux d’intérêt maintenus bas par la réglementation, de réduire les dettes après 1945.", "Cette comparaison entre r et g est au cœur des débats sur la soutenabilité de la dette, en particulier depuis la remontée des taux d’intérêt en 2022."); } },

  { id: "et2-lamal", theme: "etat", niveau: 2, type: "qcm", notion: "asymetrie-information",
    titre: "Pourquoi l’assurance maladie est-elle obligatoire ?", competence: "Identifier la défaillance du marché qu’une règle cherche à corriger.",
    enonce: P("Depuis 1996, l’assurance maladie de base est obligatoire en Suisse, et les caisses doivent accepter tout le monde au même prix dans une région, quel que soit l’état de santé. Quelle défaillance du marché ces règles visent-elles d’abord à corriger ?"),
    options: ["Une externalité, car en se soignant chacun protège aussi la santé des autres, ce que le marché ne rémunère pas.", "La sélection adverse, car sans obligation les bien-portants renonceraient à s’assurer et les primes des autres s’envoleraient.", "L’aléa moral, car une personne assurée consulte davantage, puisqu’elle ne paie plus elle-même ses soins.", "Un monopole, car sans ces règles une seule caisse finirait par dominer le marché et imposer ses prix."], c: 1, pourquoi: ["Cette externalité existe pour les maladies contagieuses. Elle justifie plutôt la vaccination que l’obligation de s’assurer et l’interdiction de trier les assurés.", null, "L’aléa moral existe, mais il apparaît après la signature du contrat et on le limite par la franchise et la quote-part. L’obligation de s’assurer répond à un problème qui se pose avant le contrat.", "Rien n’indique qu’une caisse éliminerait les autres. Le problème visé vient de l’information, l’assuré connaît mieux son état de santé que l’assureur."],
    explication: P("L’assuré connaît mieux son état de santé que l’assureur : c’est une <b>asymétrie d’information</b>. Si l’assurance est facultative, ce sont surtout les personnes à risque qui s’assurent ; les primes montent, ce qui fait fuir les autres bien-portants, et ainsi de suite : c’est la <b>sélection adverse</b>, décrite par George Akerlof en 1970 à propos des voitures d’occasion.", "L’obligation de s’assurer et l’interdiction de sélectionner les assurés évitent ce cercle vicieux. Elles s’accompagnent de subsides pour les ménages modestes, les primes étant identiques quel que soit le revenu.") },

  { id: "et2-co2", theme: "etat", niveau: 2, type: "redaction", notion: "externalite",
    titre: "Faut-il une taxe carbone plus élevée ?", competence: "Argumenter sur un instrument de politique environnementale.",
    enonce: P("La Suisse prélève une taxe CO2 sur les combustibles comme le mazout et le gaz, dont une grande partie est redistribuée à la population et aux entreprises. Le 13 juin 2021, une révision de la loi sur le CO2, qui prévoyait notamment une taxe sur les billets d’avion, a été rejetée de justesse par environ 52 % des votants.", "<b>Consigne :</b> présentez des arguments pour et contre une taxe carbone plus élevée, en utilisant la notion d’externalité. Dites ce qu’il faut faire des recettes, ou citez un autre instrument. Concluez par une prise de position explicite. Longueur attendue, 10 à 15 lignes."),
    criteres: ["La réponse explique que les émissions de CO2 sont une externalité négative et que la taxe les fait entrer dans les prix (Pigou).", "Elle présente au moins deux arguments pour : efficacité (chacun réduit là où c’est le moins cher), incitation à l’innovation, recettes redistribuables, cohérence avec les engagements climatiques…", "Elle présente au moins deux arguments contre ou difficultés : effet sur les ménages modestes et les régions périphériques, compétitivité, fuite de carbone, acceptabilité politique (vote de 2021)…", "Elle évoque la redistribution des recettes ou d’autres instruments (normes, subventions, marché de quotas).", "Elle se termine par une prise de position explicite (pour, contre ou à certaines conditions), justifiée par au moins un des arguments présentés."],
    corrige: P("Les émissions de CO2 sont une <b>externalité négative</b> : celui qui chauffe au mazout ou prend l’avion ne paie pas le coût du changement climatique qu’il contribue à provoquer. Une taxe carbone fait entrer ce coût dans les prix, comme le proposait Pigou.", "<b>Pour :</b> chacun réduit ses émissions là où c’est le moins coûteux pour lui, sans que l’État doive tout réglementer ; la taxe encourage l’innovation ; et ses recettes peuvent être redistribuées, comme en Suisse, ce qui limite son effet sur le pouvoir d’achat moyen.", "<b>Contre :</b> elle pèse davantage sur les ménages modestes et les habitants des régions mal desservies par les transports publics ; elle peut nuire à la compétitivité des entreprises exposées ou déplacer les émissions à l’étranger. Le rejet de 2021 montre aussi la difficulté de faire accepter une hausse des prix de l’énergie.", "<b>Conclusion :</b> une taxe carbone est un outil efficace, à condition de redistribuer ses recettes de façon visible, de la compléter par des investissements (transports, rénovation) et de l’introduire progressivement.") },

  { id: "et2-ostrom", theme: "etat", niveau: 2, type: "qcm", notion: "biens-communs",
    titre: "Ni le marché ni l’État ?", competence: "Connaître la troisième voie d’Elinor Ostrom.",
    enonce: P("En 1968, Garrett Hardin affirme qu’une ressource commune, comme un pâturage, est condamnée à la surexploitation, sauf à la privatiser ou à la confier à l’État. Que montre Elinor Ostrom, prix Nobel 2009 ?"),
    options: ["Que la surexploitation est bien inévitable, sauf si l’État fixe des quotas et les fait contrôler.", "Que des communautés d’usagers gèrent durablement leurs ressources avec leurs propres règles, comme les alpages de Törbel en Valais.", "Que la privatisation donne les meilleurs résultats, car chaque propriétaire ménage ce qui lui appartient.", "Que la surexploitation est rare, car les usagers limitent spontanément leurs prélèvements, sans règle ni contrôle."], c: 1, pourquoi: ["C’est l’une des deux solutions de Hardin. Ostrom montre qu’il en existe une troisième, la gestion par les usagers eux-mêmes.", null, "Ostrom montre une troisième voie, la gestion collective par les usagers, à côté du marché et de l’État.", "Ostrom ne compte pas sur la bonne volonté. Les communautés qui réussissent ont des règles précises, une surveillance et des sanctions."],
    explication: P("À partir de centaines d’études de cas, Ostrom montre qu’il existe une <b>troisième voie</b> : des communautés qui fixent elles-mêmes les règles d’accès, se surveillent et sanctionnent les tricheurs. À Törbel, une règle ancienne interdit d’envoyer sur l’alpage plus de vaches qu’on ne peut en nourrir l’hiver.", "Ces institutions réussissent à certaines conditions : limites claires, règles adaptées, participation des usagers, surveillance, sanctions graduées et reconnaissance par les autorités.") },

  /* =========================== NIVEAU 3 : AVANCÉ =========================== */
  { id: "et3-frein-calc", theme: "etat", niveau: 3, type: "calcul",
    titre: "Calculer le plafond de dépenses du frein à l’endettement", competence: "Appliquer la règle budgétaire de la Confédération (version simplifiée).",
    gen: () => { const T = rnd(76, 82) * 10, Y = T + pick([-24, -16, -8, 8, 16, 24]), rec = rnd(78, 92); return { T, Y, rec, dep: Math.round(rec * T / Y) + pick([-2, -1, 1, 2]) }; },
    enonce: (p) => P("Selon le frein à l’endettement (version simplifiée), les dépenses maximales autorisées sont égales aux recettes estimées, corrigées d’un <b>facteur conjoncturel k</b> qui compare le PIB tendanciel (le niveau atteint quand l’économie utilise normalement ses capacités) au PIB effectif. Quand l’économie tourne en dessous de son potentiel, le plafond de dépenses doit dépasser les recettes. Quand elle tourne au-dessus, il doit leur être inférieur.", `Le PIB tendanciel est de <b>${p.T} milliards</b>, le PIB effectif de <b>${p.Y} milliards</b> et les recettes estimées de <b>${p.rec} milliards</b>. Établissez k, puis calculez le plafond de dépenses et le solde autorisé (signe moins pour un déficit). Le Parlement a voté des dépenses de <b>${p.dep} milliards</b> : respectent-elles la règle ? Arrondissez k à trois décimales et les montants à deux.`),
    champs: [{ label: "Facteur conjoncturel k", unite: "", tol: 0.002 }, { label: "Plafond de dépenses", unite: "milliards", tol: 0.1 }, { label: "Solde autorisé", unite: "milliards", tol: 0.1 }, { label: "Dépenses votées", choix: ["conformes à la règle", "supérieures au plafond"] }],
    reponses: (p) => [X.arr(p.T / p.Y, 3), X.arr(p.rec * p.T / p.Y, 2), X.arr(p.rec - p.rec * p.T / p.Y, 2), p.dep <= p.rec * p.T / p.Y ? 0 : 1],
    indice: "Dans un ralentissement, le plafond doit dépasser les recettes. Cela vous dit si k est le PIB tendanciel divisé par le PIB effectif, ou l’inverse. Le solde compare ensuite les recettes au plafond.",
    correction: (p) => { const k = p.T / p.Y, pl = p.rec * k; return P(`Le plafond doit dépasser les recettes quand le PIB effectif est inférieur au PIB tendanciel. Donc k = PIB tendanciel ÷ PIB effectif = ${p.T} ÷ ${p.Y} ≈ <b>${fmt(k, 3)}</b>.`, `Plafond = ${p.rec} × ${p.T} ÷ ${p.Y} ≈ <b>${fmt(pl, 2)} milliards</b>. Solde autorisé = ${p.rec} − ${fmt(pl, 2)} = <b>${fmt(p.rec - pl, 2)} milliards</b>.`, p.dep <= pl ? `Les dépenses votées (${p.dep} milliards) restent sous le plafond de ${fmt(pl, 2)} milliards : elles sont <b>conformes à la règle</b>.` : `Les dépenses votées (${p.dep} milliards) dépassent le plafond de ${fmt(pl, 2)} milliards : elles sont <b>supérieures au plafond</b>. Il faudrait les réduire ou prévoir des recettes supplémentaires.`, k > 1 ? "L’économie est en dessous de son potentiel : un déficit est autorisé, pour ne pas aggraver le ralentissement." : "L’économie tourne au-dessus de son potentiel : un excédent est exigé, qui compensera les déficits des mauvaises années.", "Le mécanisme laisse ainsi jouer les stabilisateurs automatiques, tout en empêchant une hausse durable de la dette. Il ne contrôle pas les dépenses en soi, il les lie aux recettes corrigées de la conjoncture."); } },

  { id: "et3-multi-ouvert", theme: "etat", niveau: 3, type: "calcul", notion: "multiplicateur",
    titre: "Le multiplicateur dans une économie ouverte", competence: "Calculer un multiplicateur avec impôts et importations.",
    gen: () => ({ c: pick([0.7, 0.8, 0.9]), t: pick([0.2, 0.3, 0.4]), m: pick([0.2, 0.3, 0.4, 0.5]), g: pick([5, 10]) }),
    enonce: (p) => P(`Dans une petite économie ouverte, le revenu d’équilibre vérifie <b>Y = C + I + G + X − M</b>. La consommation dépend du revenu disponible, C = C<sub>0</sub> + c(Y − T), avec c = <b>${fmt(p.c, 2)}</b>. Les impôts sont T = T<sub>0</sub> + tY, avec t = <b>${fmt(p.t, 2)}</b>, et les importations M = M<sub>0</sub> + mY, avec m = <b>${fmt(p.m, 2)}</b>. L’investissement I, les exportations X et les constantes C<sub>0</sub>, T<sub>0</sub> et M<sub>0</sub> sont donnés.`, `Résolvez l’équation pour Y et établissez le multiplicateur de la dépense publique, puis calculez la hausse du revenu pour une dépense supplémentaire de <b>${p.g} milliards</b>. Le gouvernement envisage ensuite un budget équilibré : il relève G de ${p.g} milliards et finance cette hausse par une augmentation du même montant de l’impôt forfaitaire T<sub>0</sub>. Calculez le multiplicateur de ce budget équilibré, c’est-à-dire ΔY ÷ ΔG dans ce cas. Arrondissez à deux décimales.`),
    champs: [{ label: "Multiplicateur de G", unite: "", tol: 0.01 }, { label: "Hausse du revenu", unite: "milliards", tol: 0.06 }, { label: "Multiplicateur du budget équilibré", unite: "", tol: 0.01 }],
    reponses: (p) => { const k = 1 / (1 - p.c * (1 - p.t) + p.m); return [X.arr(k, 2), X.arr(k * p.g, 2), X.arr((1 - p.c) * k, 2)]; },
    indice: "Remplacez C, T et M par leurs expressions dans l’identité, puis regroupez tous les termes en Y du même côté. Pour le budget équilibré, ΔG et ΔT<sub>0</sub> agissent en même temps et la hausse d’impôt réduit la consommation de c fois son montant.",
    correction: (p) => { const k = 1 / (1 - p.c * (1 - p.t) + p.m), den = 1 - p.c * (1 - p.t) + p.m; return P("On remplace dans l’identité : Y = C<sub>0</sub> + c(Y − T<sub>0</sub> − tY) + I + G + X − M<sub>0</sub> − mY.", `En regroupant les termes en Y, Y × [1 − c(1 − t) + m] = C<sub>0</sub> − cT<sub>0</sub> + I + G + X − M<sub>0</sub>. Donc ΔY = ΔG ÷ [1 − c(1 − t) + m] et le multiplicateur est k = 1 ÷ [1 − c(1 − t) + m].`, `c(1 − t) = ${fmt(p.c, 2)} × ${fmt(1 - p.t, 2)} = ${fmt(p.c * (1 - p.t), 3)}, donc k = 1 ÷ (1 − ${fmt(p.c * (1 - p.t), 3)} + ${fmt(p.m, 2)}) = 1 ÷ ${fmt(den, 3)} ≈ <b>${fmt(k, 2)}</b>.`, `Hausse du revenu = k × ${p.g} ≈ <b>${fmt(X.arr(k * p.g, 2), 2)} milliards</b>.`, `Budget équilibré : ΔG = ΔT<sub>0</sub> = ${p.g}. La hausse d’impôt retire ${fmt(p.c, 2)} × ${p.g} de consommation, donc ΔY = (ΔG − cΔT<sub>0</sub>) ÷ ${fmt(den, 3)} = (1 − ${fmt(p.c, 2)}) × ${p.g} ÷ ${fmt(den, 3)}. Le multiplicateur vaut (1 − c) × k = ${fmt(1 - p.c, 2)} × ${fmt(k, 2)} ≈ <b>${fmt(X.arr((1 - p.c) * k, 2), 2)}</b>.`, `Le multiplicateur de G est bien plus faible qu’en économie fermée sans impôt (${fmt(1 / (1 - p.c), 1)}) : une partie de chaque franc dépensé part en impôts ou en importations. Le budget équilibré reste expansionniste, mais bien moins qu’une dépense financée par la dette, puisque l’impôt retire du pouvoir d’achat aux ménages. Dans une petite économie très ouverte comme la Suisse, une relance profite en partie aux pays voisins.`); } },

  { id: "et3-perte-ext", theme: "etat", niveau: 3, type: "calcul", notion: "externalite",
    titre: "Le coût social d’une externalité", competence: "Calculer la perte de bien-être due à une externalité non corrigée.",
    gen: genExt,
    enonce: (p) => P(`Sur un marché, la demande est <b>P = ${p.a} − Q</b>, le coût marginal privé des producteurs <b>Cm = ${p.c} + Q</b>, et chaque unité produite cause un dommage marginal de <b>${p.e} francs</b> à des tiers.`, `Établissez le coût marginal social et calculez la quantité de marché et la quantité optimale. Calculez ensuite la perte sèche pour la société quand l’externalité n’est pas corrigée (la surface entre la demande et le coût marginal social, sur les unités produites en trop). L’État hésite sur le montant de la taxe et la fixe à la moitié du dommage, soit <b>${fmt(p.e / 2)} francs</b> par unité : quelle perte sèche subsiste alors ?`),
    champs: [{ label: "Quantité de marché", unite: "unités", tol: 0.05 }, { label: "Quantité optimale", unite: "unités", tol: 0.05 }, { label: "Perte sèche sans taxe", unite: "fr.", tol: 0.05 }, { label: "Perte sèche avec la demi-taxe", unite: "fr.", tol: 0.05 }],
    reponses: (p) => [p.Qm, p.Qm - p.e / 2, X.arr(p.e * p.e / 4, 2), X.arr(p.e * p.e / 16, 2)],
    indice: "Le coût marginal social est le coût privé plus le dommage. Chaque perte est un triangle, dont la base est l’écart entre la quantité produite et la quantité optimale et dont la hauteur est l’écart entre coût social et demande à la quantité produite. Une taxe t déplace le coût marginal privé vers le haut de t.",
    correction: (p) => { const dQ = p.e / 2, Qo = p.Qm - dQ, t = p.e / 2, Qt = (p.a - p.c - t) / 2, d2 = Qt - Qo; return P(`Coût marginal social = ${p.c} + Q + ${p.e}. Sans intervention, ${p.a} − Q = ${p.c} + Q donne Q = <b>${p.Qm}</b>. À l’optimum, ${p.a} − Q = ${p.c} + Q + ${p.e} donne Q = <b>${fmt(Qo)}</b>. Les unités en trop sont ${p.Qm} − ${fmt(Qo)} = ${fmt(dQ)}.`, `À la quantité de marché, le coût social dépasse la demande de ${p.e} francs (le coût social vaut ${p.c + p.Qm + p.e}, la demande ${p.a - p.Qm}). Ce triangle a pour base ${fmt(dQ)} et pour hauteur ${p.e}. Perte sèche = ½ × ${p.e} × ${fmt(dQ)} = <b>${fmt(0.5 * p.e * dQ)} francs</b>.`, `Avec une taxe de ${fmt(t)} francs, ${p.a} − Q = ${p.c} + Q + ${fmt(t)} donne Q = ${fmt(Qt)}. Il reste ${fmt(d2)} unité${d2 >= 2 ? "s" : ""} en trop. À cette quantité, l’écart entre coût social et demande est de ${fmt(2 * d2)} francs. Perte sèche = ½ × ${fmt(d2)} × ${fmt(2 * d2)} = <b>${fmt(d2 * d2)} francs</b>.`, "La demi-taxe divise la perte par quatre, et non par deux : la perte croît avec le carré de l’écart à l’optimum. Une taxe imparfaite corrige déjà l’essentiel, mais ne supprime pas toute la perte. Même à l’optimum, il reste de la pollution : la quantité optimale n’est pas nulle, elle est celle où le bénéfice de la dernière unité compense son coût total."); } },

  { id: "et3-ricardien", theme: "etat", niveau: 3, type: "qcm", notion: "equivalence-ricardienne",
    titre: "L’équivalence ricardienne", competence: "Comprendre une objection à l’efficacité des relances.",
    enonce: P("Un gouvernement baisse les impôts de 1 000 francs par ménage cette année, en finançant la mesure par un emprunt qui sera remboursé par des impôts plus élevés dans vingt ans. L’équivalence ricardienne (Robert Barro, 1974) prédit que cette baisse ne fera pas augmenter la consommation. Pour quel type de ménage cette prédiction a-t-elle le moins de chances de se vérifier ?"),
    options: ["Un ménage prévoyant, qui souhaite léguer un patrimoine à ses enfants et sait qu’ils paieront la dette.", "Un ménage qui a lu le budget de l’État et anticipe la hausse d’impôts décidée pour rembourser la dette.", "Un ménage sans épargne, qui ne peut pas emprunter et consomme aussitôt chaque franc qu’il reçoit.", "Un ménage aisé, qui place la baisse d’impôt sur un compte d’épargne en attendant les impôts futurs."], c: 2, pourquoi: ["Ce ménage correspond à l’hypothèse de Barro : il se soucie de ses descendants et met de côté de quoi payer leurs impôts futurs. Sa consommation ne change pas.", "Un ménage informé qui anticipe la hausse d’impôts épargne la baisse actuelle. C’est le comportement que prédit Barro.", null, "Ce ménage épargne la baisse d’impôt, comme le prédit Barro. Il peut le faire sans contrainte, ce qui est précisément la condition de l’équivalence."],
    explication: P("L’équivalence ricardienne suppose des ménages qui voient venir les impôts futurs, qui se soucient de leurs descendants et qui peuvent emprunter ou épargner librement. Dans ce cas, ils épargnent la baisse d’impôt pour payer ces impôts futurs, et la relance est sans effet.", "Elle échoue pour un ménage sans épargne et sans accès au crédit. Il dépense les 1 000 francs, car il ne peut pas lisser sa consommation dans le temps, et la baisse d’impôt relance la demande. Les études empiriques montrent que de nombreux ménages modestes se comportent ainsi, ce qui explique que l’équivalence ne se vérifie que partiellement. Ricardo lui-même doutait qu’elle s’observe en pratique.") },

  { id: "et3-vf-alea", theme: "etat", niveau: 3, type: "vf", notion: "alea-moral",
    titre: "Aléa moral et assurance", competence: "Reconnaître l’aléa moral et ses remèdes.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["L’aléa moral désigne le fait qu’une personne assurée peut prendre plus de risques, car elle n’en supporte plus toutes les conséquences.", true, "Par exemple, un conducteur bien assuré peut être moins prudent ; une banque qu’on sait sauvée en cas de crise peut prendre trop de risques."],
      ["La franchise de l’assurance maladie suisse sert notamment à limiter l’aléa moral.", true, "En faisant payer une partie des frais à l’assuré, elle l’incite à ne pas consommer de soins inutiles."],
      ["L’aléa moral et la sélection adverse sont deux noms du même phénomène.", false, "La <b>sélection adverse</b> concerne l’information cachée <b>avant</b> le contrat (qui choisit de s’assurer) ; l’<b>aléa moral</b> concerne le comportement caché <b>après</b> le contrat."],
      ["Savoir qu’une banque est « trop grande pour faire faillite », et que l’État la sauvera, réduit son aléa moral.", false, "Cette garantie implicite l’augmente. Si une banque sait qu’elle sera sauvée, ses dirigeants, ses actionnaires et ses créanciers acceptent plus de risques. La réglementation suisse dite « too big to fail », adoptée en 2011 et en vigueur depuis 2012, cherche à corriger ce biais par des fonds propres plus élevés et des plans de liquidation."]
    ] },

  { id: "et3-samuelson", theme: "etat", niveau: 3, type: "calcul", notion: "bien-public",
    titre: "Faut-il construire le bien public ?", competence: "Appliquer la condition de Samuelson à un bien public.",
    gen: () => { const n = 3; let w, cost; do { w = Array.from({ length: n }, () => rnd(4, 20) * 100); cost = rnd(20, 45) * 100; } while (Math.abs(w.reduce((a, b) => a + b, 0) - cost) < 300 || w.some((x) => x - (w.reduce((a, b) => a + b, 0) - cost) / 3 < 100)); return { w, cost }; },
    enonce: (p) => P(`Trois ménages vivent au bout d’un chemin non éclairé. Ils seraient prêts à payer respectivement <b>${p.w.map((x) => fmt(x)).join(", ")} francs</b> pour l’installation d’un éclairage, qui profiterait aux trois. L’installation coûte <b>${fmt(p.cost)} francs</b>.`, "Calculez le gain net pour l’ensemble des ménages (signe moins si le coût dépasse ce que les ménages sont prêts à payer) et dites s’il faut construire. Si le projet est réalisé, on répartit ensuite son coût pour que les trois ménages aient le même gain net. Calculez la contribution du ménage 1 dans ce partage, arrondie au franc. Si vous répondez qu’il ne faut pas construire, calculez-la quand même : elle montre qu’aucun partage ne rend alors les trois ménages gagnants."),
    champs: [{ label: "Gain net", unite: "fr.", tol: 0.5 }, { label: "Faut-il construire ?", choix: ["oui", "non"] }, { label: "Contribution du ménage 1", unite: "fr.", tol: 1 }],
    reponses: (p) => { const G = p.w.reduce((a, b) => a + b, 0) - p.cost; return [G, G > 0 ? 0 : 1, X.arr(p.w[0] - G / 3, 0)]; },
    indice: "Pour un bien public, on additionne les dispositions à payer de tous ceux qui en profitent. Dans le partage, chaque ménage paie sa disposition à payer diminuée d’un même montant, qui est son gain net.",
    correction: (p) => { const s = p.w.reduce((a, b) => a + b, 0), G = s - p.cost, g3 = G / 3; return P(`Somme des dispositions à payer : ${p.w.map((x) => fmt(x)).join(" + ")} = ${fmt(s)} francs.`, `Gain net = ${fmt(s)} − ${fmt(p.cost)} = <b>${fmt(G)} francs</b>.`, G > 0 ? `Le gain net est positif : <b>il faut construire</b> l’éclairage, qui est souhaitable pour l’ensemble des ménages. Pourtant, un ménage seul n’a en général pas intérêt à payer ${fmt(p.cost)} francs, et chacun peut espérer que les autres paient : sans organisation collective, il risque de ne pas être construit.` : "Le gain net est négatif : l’éclairage coûte plus qu’il ne rapporte aux ménages, <b>il ne faut pas le construire</b>.", `Pour que les trois ménages aient le même gain net, chacun a un gain net de ${fmt(G)} ÷ 3 = ${fmt(g3, 2)} franc${Math.abs(g3) >= 2 ? "s" : ""} et paie sa disposition à payer diminuée de ce gain. Le ménage 1 paie ${fmt(p.w[0])} − (${fmt(g3, 2)}) ≈ <b>${fmt(p.w[0] - g3, 0)} francs</b>. Les trois contributions totalisent bien ${fmt(p.cost)} francs.`, G > 0 ? `Un partage à parts égales, soit ${fmt(p.cost / 3, 0)} francs par ménage, ne conviendrait pas toujours. ${p.w.some((x) => x < p.cost / 3) ? "Ici, au moins un ménage valorise l’éclairage moins que sa part et y perdrait, alors que le projet est avantageux pour l’ensemble. " : "Ici chacun y gagnerait, mais ce n’est pas garanti en général. "}Un partage qui laisse chacun gagnant existe toujours quand le gain net est positif, mais il suppose de connaître les dispositions à payer de chacun, qu’aucun ménage n’a intérêt à révéler.` : "Quand la somme des dispositions à payer est inférieure au coût, aucun partage ne laisse chaque ménage gagnant : si tous paient leur disposition à payer, il manque encore de quoi couvrir le coût.", "C’est la version la plus simple de la condition de Samuelson (1954). Pour un bien public, on additionne les dispositions à payer de tous les bénéficiaires et on compare cette <b>somme</b> au coût. Quand la quantité peut varier, on produit jusqu’au point où la somme des dispositions marginales à payer est égale au coût marginal. Pour un bien privé, au contraire, chacun compare son propre bénéfice au prix."); } },

  { id: "et3-poste", theme: "etat", niveau: 3, type: "redaction", notion: "choix-public",
    titre: "Les services publics doivent-ils rester publics ?", competence: "Argumenter sur la frontière entre marché et État.",
    enonce: P("La Poste, les CFF et Swisscom sont des entreprises détenues en tout ou en majorité par la Confédération. Le marché des télécommunications a été ouvert à la concurrence, tandis que La Poste garde un monopole sur les lettres légères et doit assurer un service universel dans tout le pays.", "<b>Consigne :</b> faut-il ouvrir davantage ces services à la concurrence, voire les privatiser ? Présentez les arguments des deux côtés, en utilisant au moins une notion d’économie. Appuyez-vous sur au moins un exemple de secteur. Rattachez chaque position à une école ou à un auteur (par exemple l’école des choix publics de Buchanan et Niskanen, la théorie du monopole naturel, les marchés contestables de Baumol), et dites sur quelle hypothèse ils s’opposent. Concluez par une prise de position explicite. Longueur attendue, 15 à 25 lignes."),
    criteres: ["La réponse présente au moins deux arguments pour l’ouverture ou la privatisation : efficacité, innovation, baisse des prix grâce à la concurrence, limites de la gestion publique (choix publics)…", "Elle présente au moins deux arguments pour le maintien public : service universel dans les régions périphériques, monopole naturel des réseaux, externalités positives, sécurité d’approvisionnement…", "Elle mobilise au moins une notion : monopole naturel, concurrence, bien public, externalité, service universel, défaillance du marché ou de l’État…", "Elle s’appuie sur au moins un exemple : télécommunications, chemins de fer, poste, électricité, expériences étrangères…", "La réponse nomme au moins deux écoles ou auteurs et l’hypothèse qui les sépare.", "Elle se termine par une prise de position explicite (pour, contre ou à certaines conditions), justifiée par au moins un des arguments présentés."],
    corrige: P("<b>Ce qui oppose les écoles :</b> l’école des choix publics (James Buchanan, William Niskanen) suppose que les dirigeants d’une entreprise publique et les élus poursuivent leur propre intérêt, par exemple agrandir leur budget, et que rien ne les oblige à maîtriser les coûts. La théorie du monopole naturel suppose au contraire que, pour un réseau, un seul opérateur produit à moindre coût, de sorte que la concurrence gaspille des ressources. Les deux positions s’opposent donc sur l’hypothèse qui compte : l’incitation des gestionnaires ou la structure des coûts. William Baumol nuance la seconde : si l’entrée sur le marché est libre et sans coût perdu, la menace d’un concurrent discipline même un monopole (marchés contestables), ce qui ne tient guère pour un réseau ferré.", "<b>Pour l’ouverture :</b> la concurrence pousse les entreprises à innover et à baisser leurs prix, comme l’a montré l’ouverture des télécommunications en Suisse à la fin des années 1990. La théorie des <b>choix publics</b> rappelle que les entreprises publiques peuvent être influencées par des intérêts politiques et manquer d’incitations à l’efficacité.", "<b>Pour le maintien public :</b> certains réseaux, comme le rail, sont des <b>monopoles naturels</b> : il serait absurde de construire deux voies concurrentes. Le marché ne desservirait pas spontanément les vallées et villages peu rentables, alors que la cohésion du pays l’exige : c’est le <b>service universel</b>. Les transports publics ont aussi des externalités positives, comme la réduction des embouteillages et de la pollution.", "<b>Conclusion :</b> la réponse dépend du secteur : on peut ouvrir à la concurrence les services où plusieurs opérateurs peuvent coexister, tout en gardant sous contrôle public les réseaux en monopole naturel et en finançant explicitement le service universel.") },

  { id: "et3-comparaison", theme: "etat", niveau: 3, type: "document",
    titre: "Comparer le poids de l’État entre pays", competence: "Interpréter une comparaison internationale avec esprit critique.",
    enonce: P("Dépenses des administrations publiques, en % du PIB (ordres de grandeur, années 2020) :") +
      `<table><thead><tr><th>France</th><th>Suède</th><th>Allemagne</th><th>États-Unis</th><th>Suisse</th></tr></thead><tbody><tr><td>environ 57 %</td><td>environ 50 %</td><td>environ 48 %</td><td>environ 39 %</td><td>environ 33 %</td></tr></tbody></table><p class="ex-source">Source : OCDE, Government at a Glance 2025 ; ordres de grandeur arrondis.</p>` +
      P("Quelle conclusion est la plus prudente ?"),
    options: ["Les Suisses paient beaucoup moins pour leur santé et leurs retraites que les Français, puisque leur État dépense moins.","Les services publics sont forcément de meilleure qualité en France, puisque l’État y dépense davantage.","L’État suisse dépense moins, mais une partie des dépenses obligatoires y passe par des caisses privées.","Les États-Unis ont l’État le plus généreux de ces pays, car leur économie est la plus grande."], c: 2, pourquoi: ["Le tableau mesure les dépenses publiques, pas ce que paient les ménages. En Suisse, les primes d’assurance maladie et les cotisations au deuxième pilier sont obligatoires, mais versées à des caisses privées.", "Le tableau donne des montants dépensés, pas la qualité des services. Dépenser plus ne garantit pas un meilleur résultat.", null, "Avec environ 39 % du PIB, les États-Unis sont avant-derniers du tableau, devant la Suisse seulement."],
    explication: P("Ces chiffres ne comparent pas tout à fait la même chose. En Suisse, les primes d’assurance maladie obligatoire et les cotisations au deuxième pilier sont versées à des caisses privées : ce sont des dépenses <b>obligatoires</b>, mais elles n’apparaissent pas comme dépenses publiques. Dans d’autres pays, les mêmes services passent par l’État.", "En les ajoutant, l’écart entre la Suisse et ses voisins se réduit nettement. Les comparaisons internationales doivent toujours être lues en se demandant ce qu’elles mesurent exactement.") },
  { id: "et1-fait-valeur", theme: "etat", niveau: 1, type: "vf", typeLib: "Constat ou jugement de valeur", etiquettes: ["Constat", "Jugement de valeur"],
    titre: "Un jugement de valeur sous une apparence de fait", competence: "Repérer le jugement de valeur caché dans une phrase d’apparence factuelle et reconnaître qu’une prévision se vérifie.",
    enonce: P("Un <b>constat</b> se vérifie avec des données, même s’il se révèle faux. Une <b>prévision</b> aussi, une fois le temps écoulé. Un <b>jugement de valeur</b> repose sur une appréciation de ce qui est bon, juste ou excessif, même quand la phrase est formulée comme un fait. Ici, aucune phrase ne contient de marqueur comme « devrait » ou « injuste ». Classez chaque affirmation."),
    affirmations: [
      ["Un État qui prélève plus de la moitié du PIB étouffe l’initiative privée.", false, "C’est un jugement de valeur déguisé. On peut mesurer la part des prélèvements, mais « étouffe » suppose un seuil à partir duquel l’État en fait trop, et ce seuil est une appréciation. Deux observateurs d’accord sur le chiffre peuvent donc s’opposer sur la conclusion."],
      ["Une hausse de 10 % du prix des cigarettes, par une taxe, fera baisser leur consommation.", true, "C’est une prévision, donc un constat que l’on peut tester : il suffit de comparer la consommation avant et après la hausse, comme l’ont fait de nombreuses études. Elle peut se révéler fausse ou trop forte, sans cesser d’être vérifiable."],
      ["En France, les dépenses publiques dépassent la moitié du PIB.", true, "On peut le vérifier avec des données : l’OCDE et l’institut statistique publient ce ratio. L’exercice ne dit pas si ce niveau est trop élevé ou non, ce qui serait un jugement."],
      ["L’impôt progressif pénalise ceux qui réussissent.", false, "C’est un jugement de valeur déguisé. Que les plus hauts revenus paient un taux plus élevé est un fait, mais « pénalise » le présente comme une sanction injuste, alors que d’autres y voient une juste contribution."]] },
  ]);
  /* =========================== COMPLÉMENTS : séries portées à douze exercices (novembre 2026) =========================== */
  X.add([
  /* ----- Niveau 1 ----- */
  { id: "et1-tva", theme: "etat", niveau: 1, type: "calcul",
    titre: "Calculer la TVA d’une facture", competence: "Passer d’un prix hors taxe à un prix toutes taxes comprises.",
    gen: () => ({ ht: rnd(8, 60) * 10 }),
    enonce: (p) => P(`Un artisan établit une facture de <b>${p.ht} francs</b> hors taxe. Il doit y ajouter la taxe sur la valeur ajoutée, au taux normal de <b>8,1 %</b> en vigueur en Suisse depuis 2024.`, "Calculez le montant de la taxe, puis le prix toutes taxes comprises."),
    champs: [{ label: "Montant de la TVA", unite: "fr.", tol: 0.01 }, { label: "Prix toutes taxes comprises", unite: "fr.", tol: 0.01 }],
    reponses: (p) => [Math.round(p.ht * 8.1) / 100, Math.round(p.ht * 108.1) / 100],
    indice: "La taxe se calcule sur le prix hors taxe. Elle s’ajoute ensuite à ce prix.",
    correction: (p) => P("La taxe est un pourcentage du prix hors taxe.", `TVA = ${p.ht} × 8,1 ÷ 100 = <b>${fmt(p.ht * 0.081)} francs</b>.`, `Prix toutes taxes comprises = ${p.ht} + ${fmt(p.ht * 0.081)} = <b>${fmt(p.ht * 1.081)} francs</b>.`, "L’artisan encaisse la taxe pour le compte de l’État et la lui reverse, après avoir déduit celle qu’il a payée sur ses propres achats. C’est le client final qui la supporte. La TVA est la première recette de la Confédération.") },

  { id: "et1-graph-budget", theme: "etat", niveau: 1, type: "graphique",
    titre: "Recettes, dépenses et déficit", competence: "Repérer un déficit et un excédent sur un graphique à deux séries.",
    enonce: P("Le graphique compare les recettes et les dépenses d’une commune pendant cinq ans, en millions de francs.", "Que montre-t-il ?"),
    fig: () => X.barres({ cats: ["2020", "2021", "2022", "2023", "2024"], vals: [50, 52, 53, 55, 58], vals2: [48, 51, 56, 57, 56], noms: ["Recettes", "Dépenses"], ymax: 66, dec: 0, aria: "Recettes et dépenses d’une commune de 2020 à 2024", caption: "En millions de francs. Données inventées pour l’exercice." }),
    options: ["La commune est en déficit en 2022 et en 2023, pour 5 millions au total.", "La commune est en excédent en 2022 et en 2023, pour 5 millions au total.", "La commune est en déficit chaque année, puisque ses dépenses augmentent.", "La commune n’est en déficit qu’en 2022, l’année où ses dépenses augmentent le plus."], c: 0,
    pourquoi: [null, "Ces deux années, la barre des dépenses dépasse celle des recettes. La commune dépense plus qu’elle n’encaisse. C’est un déficit.", "Des dépenses qui augmentent ne créent pas un déficit si les recettes augmentent autant. En 2020, en 2021 et en 2024, les recettes dépassent les dépenses.", "En 2023, les dépenses (57 millions) dépassent encore les recettes (55 millions). Le déficit dure deux ans."],
    explication: P("Solde = recettes − dépenses. En 2022, 53 − 56 = <b>−3 millions</b>. En 2023, 55 − 57 = <b>−2 millions</b>. Les trois autres années, le solde est positif.", "Les déficits cumulés atteignent 5 millions. La commune les finance en empruntant, ce qui augmente sa dette, ou en puisant dans les excédents des années précédentes.") },

  { id: "et1-doc-projets", theme: "etat", niveau: 1, type: "document",
    titre: "Choisir entre plusieurs projets publics", competence: "Comparer des projets publics par leurs coûts et leurs bénéfices.",
    enonce: P("Une commune dispose de 5 millions de francs. Ses services ont estimé le coût de trois projets et les bénéfices qu’en tireraient les habitants.") +
      `<table><thead><tr><th>Projet</th><th>Coût (millions)</th><th>Bénéfices estimés (millions)</th></tr></thead><tbody><tr><td>A. Piste cyclable</td><td>2</td><td>3</td></tr><tr><td>B. Salle polyvalente</td><td>5</td><td>4,5</td></tr><tr><td>C. Rénovation de l’école</td><td>3</td><td>6</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P("Quels projets retenir pour que les habitants y gagnent le plus ?"),
    options: ["Les projets A et C, dont les gains nets atteignent ensemble 4 millions.", "Le projet B, le plus important, qui utilise exactement le budget.", "Le projet C seul, celui dont les bénéfices sont les plus élevés.", "Les trois projets, puisque chacun est utile aux habitants."], c: 0,
    pourquoi: [null, "Le projet B coûte 5 millions et n’en rapporte que 4,5. Les habitants y perdraient un demi-million.", "Le projet C a le gain net le plus élevé, 3 millions. Mais il reste 2 millions, qui suffisent pour le projet A et son gain net de 1 million.", "Les trois projets coûtent 10 millions, le double du budget. Et le projet B coûte plus qu’il ne rapporte."],
    explication: P("Gain net = bénéfices − coût. Projet A : 3 − 2 = <b>+1 million</b>. Projet B : 4,5 − 5 = <b>−0,5 million</b>. Projet C : 6 − 3 = <b>+3 millions</b>.", "Avec 5 millions, la commune peut financer A et C (2 + 3 = 5 millions) et obtenir un gain net de 4 millions. Le projet B est à écarter, même s’il était le seul finançable.", "C’est le principe de l’analyse coûts-bénéfices. Sa difficulté est d’estimer les bénéfices, par exemple le temps gagné ou les accidents évités, qui n’ont pas de prix de marché.") },

  /* ----- Niveau 2 ----- */
  { id: "et2-graph-externalite", theme: "etat", niveau: 2, type: "graphique", notion: "externalite",
    titre: "Une externalité négative sur un graphique", competence: "Comparer sur un graphique l’équilibre du marché et l’optimum social en présence d’une externalité.",
    enonce: P("Une usine produit un bien dont la fabrication pollue une rivière. Le graphique montre la demande, le coût marginal privé de l’usine et le coût marginal social, qui ajoute le dommage causé aux riverains, soit 20 francs par unité.", "Quelle lecture est correcte ?"),
    fig: () => X.graphe({ xmax: 76, ymax: 108, ylab: "Prix et coûts (fr.)", xlab: "Quantité", aria: "Externalité négative : le coût marginal social est au-dessus du coût marginal privé",
      zones: [{ pts: [[30, 70], [40, 80], [40, 60]], col: "r" }],
      gx: [[30, "30"], [40, "40"]], gy: [[60, "60"], [70, "70"], [80, "80"]], reperes: [[30, 70], [40, 80]],
      lignes: [{ pts: [[0, 100], [68, 32]], col: "d", lab: "demande", at: [68, 32], dx: 4, dy: 16, anc: "end" }, { pts: [[0, 20], [60, 80]], col: "o", lab: "coût privé", at: [60, 80], dx: 6, dy: 14 }, { pts: [[0, 40], [56, 96]], col: "r", lab: "coût social", at: [56, 96], dx: 6, dy: 4 }],
      points: [{ x: 40, y: 60, lab: "M", dx: 20, dy: 6 }, { x: 30, y: 70, lab: "S", col: "r", dx: -8, dy: -10, anc: "end" }],
      caption: "Demande P = 100 − Q, coût marginal privé 20 + Q, coût marginal social 40 + Q." }),
    options: ["Le marché produit 40 unités, soit 10 de trop, et la surface colorée mesure la perte pour la société, 100 francs.", "Le marché produit 30 unités, la quantité pour laquelle le coût marginal social est égal au prix.", "Le marché produit 40 unités, et la surface colorée est la recette d’une taxe de 20 francs par unité.", "Le marché produit 40 unités, une quantité optimale puisque acheteurs et vendeurs sont d’accord."], c: 0,
    pourquoi: [null, "L’usine ne tient compte que de son coût privé. Elle produit jusqu’au point M, soit 40 unités. La quantité de 30 unités est celle qu’il faudrait atteindre.", "Une taxe de 20 francs sur 30 unités rapporterait 600 francs, un rectangle. Le triangle coloré mesure autre chose, le coût des 10 unités produites en trop, au-delà de ce qu’elles valent pour les acheteurs.", "Acheteurs et vendeurs sont d’accord, mais les riverains ne participent pas à l’échange. Le coût qu’ils subissent n’entre dans le calcul de personne."],
    explication: P("Le marché s’équilibre là où la demande coupe le coût <b>privé</b> : 100 − Q = 20 + Q, soit Q = <b>40</b> (point M). L’optimum social est là où elle coupe le coût <b>social</b> : 100 − Q = 40 + Q, soit Q = <b>30</b> (point S).", "Entre 30 et 40 unités, chaque unité coûte à la société plus qu’elle ne vaut pour son acheteur. La perte est le triangle coloré, ½ × 10 × 20 = <b>100 francs</b>.", "Arthur Pigou proposait une taxe égale au dommage, ici 20 francs par unité, qui ramène la production à 30. Ronald Coase a montré qu’une négociation entre l’usine et les riverains peut aboutir au même résultat quand elle est peu coûteuse, ce qui est rare dès que les victimes sont nombreuses.") },

  { id: "et2-incidence-cotis", theme: "etat", niveau: 2, type: "calcul",
    titre: "Qui supporte une cotisation sociale ?", competence: "Calculer le partage d’un prélèvement à partir des élasticités de l’offre et de la demande.",
    gen: () => ({ t: pick([4, 6, 8, 10]), eo: pick([0.1, 0.2, 0.25]), ed: pick([0.3, 0.5, 0.75, 1]) }),
    enonce: (p) => P(`Un pays instaure une cotisation de <b>${p.t} %</b> du salaire, versée par les employeurs. L’élasticité de l’offre de travail est de <b>${fmt(p.eo)}</b>, celle de la demande de travail de <b>${fmt(p.ed)}</b> en valeur absolue.`, "La part d’un prélèvement supportée par les salariés vaut l’élasticité de la demande divisée par la somme des deux élasticités. Calculez cette part (en %, une décimale), puis la baisse du salaire reçu par les salariés, en points de pourcentage (deux décimales)."),
    champs: [{ label: "Part supportée par les salariés", unite: "%", tol: 0.1 }, { label: "Baisse du salaire", unite: "points", tol: 0.02 }],
    reponses: (p) => { const s = p.ed / (p.ed + p.eo); return [Math.round(s * 1000) / 10, Math.round(p.t * s * 100) / 100]; },
    indice: "Le côté du marché qui réagit le moins au prix supporte la plus grande part. Ici, comparez 0 virgule quelque chose pour l’offre à la valeur donnée pour la demande.",
    correction: (p) => { const s = p.ed / (p.ed + p.eo); return P(`Part des salariés = ${fmt(p.ed)} ÷ (${fmt(p.ed)} + ${fmt(p.eo)}) = ${fmt(p.ed)} ÷ ${fmt(p.ed + p.eo)}`, `≈ <b>${fmt(s * 100, 1)} %</b>.`, `Baisse du salaire = ${p.t} × ${fmt(s, 3)} ≈ <b>${fmt(p.t * s, 2)} points</b>. Le coût du travail pour l’employeur n’augmente que de ${fmt(p.t * (1 - s), 2)} point${p.t * (1 - s) >= 2 ? "s" : ""}.`, "L’offre de travail réagit peu au salaire, car la plupart des gens ont besoin de travailler. Les salariés supportent donc l’essentiel de la cotisation, même quand la loi la met à la charge de l’employeur. Celui qui verse un prélèvement n’est pas forcément celui qui le supporte."); } },

  { id: "et2-doc-primaire", theme: "etat", niveau: 2, type: "document",
    titre: "Solde primaire et solde total", competence: "Distinguer le solde primaire du solde total d’un budget public.",
    enonce: P("Voici le budget d’un État pour une année, en milliards.") +
      `<table><thead><tr><th>Poste</th><th>Montant</th></tr></thead><tbody><tr><td>Recettes</td><td>100</td></tr><tr><td>Dépenses hors intérêts de la dette</td><td>97</td></tr><tr><td>Intérêts de la dette</td><td>5</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P("Quelle lecture est correcte ?"),
    options: ["Le solde primaire est un excédent de 3 milliards, et le solde total un déficit de 2 milliards.", "Le solde primaire est un déficit de 2 milliards, et le solde total un excédent de 3 milliards.", "Le budget est en excédent de 3 milliards, puisque les recettes dépassent les dépenses.", "Le budget est équilibré, puisque les intérêts ne sont pas une dépense de l’année."], c: 0,
    pourquoi: [null, "Les deux soldes sont inversés. Le solde primaire laisse de côté les intérêts (100 − 97), le solde total les inclut (100 − 102).", "Les recettes ne dépassent que les dépenses hors intérêts. En ajoutant les 5 milliards d’intérêts, les dépenses atteignent 102 milliards.", "Les intérêts sont bien payés pendant l’année. Ils viennent de la dette passée, mais ils pèsent sur le budget présent."],
    explication: P("Solde primaire = recettes − dépenses hors intérêts = 100 − 97 = <b>+3 milliards</b>. Solde total = 100 − 97 − 5 = <b>−2 milliards</b>.", "Le solde primaire dit si l’État vit selon ses moyens du moment. Le solde total ajoute le poids du passé. Ici l’État couvre ses dépenses courantes, mais pas la totalité de ses intérêts, et sa dette augmente de 2 milliards.", "Cette distinction commande la dynamique de la dette. Quand le taux d’intérêt dépasse le taux de croissance, il faut un excédent primaire pour stabiliser la dette en proportion du PIB.") },

  { id: "et2-coase", theme: "etat", niveau: 2, type: "qcm", notion: "externalite",
    titre: "Négocier plutôt que réglementer", competence: "Appliquer le raisonnement de Coase à un conflit de voisinage.",
    enonce: P("Un atelier fait du bruit. La gêne de son unique voisin est évaluée à 3 000 francs par an. Une isolation qui supprimerait le bruit coûterait 1 000 francs par an à l’atelier. La loi donne au voisin le droit au calme, et les deux parties peuvent négocier sans frais.", "Que prévoit le raisonnement de Ronald Coase ?"),
    options: ["L’atelier pose l’isolation, et il le ferait aussi avec un droit au bruit, le voisin la lui payant.", "L’atelier verse 3 000 francs par an au voisin pour sa gêne et continue de travailler sans isolation.", "L’atelier cesse son activité, car le droit au calme du voisin l’emporte sur son intérêt.", "L’atelier pose l’isolation, mais il ne le ferait pas si la loi lui donnait le droit au bruit."], c: 0,
    pourquoi: [null, "Dédommager le voisin coûterait 3 000 francs, isoler n’en coûte que 1 000. L’atelier choisit la solution la moins chère.", "Fermer coûterait bien plus que 1 000 francs par an. L’atelier respecte le droit du voisin au moindre coût, en isolant.", "Avec le droit au bruit, le voisin a intérêt à payer l’isolation, qui lui coûte 1 000 francs et lui en épargne 3 000. Le bruit cesse dans les deux cas. Seul change celui qui paie."],
    explication: P("L’isolation coûte 1 000 francs et supprime une gêne de 3 000 francs. Elle est donc souhaitable, et la négociation y conduit quel que soit le détenteur du droit.", "Si le voisin a droit au calme, l’atelier isole à ses frais. Si l’atelier a le droit au bruit, le voisin lui paie l’isolation. Le résultat est le même, seule la <b>répartition</b> du coût change. C’est le théorème de Coase (1960).", "Sa condition est essentielle. Il faut que les droits soient clairement définis et que négocier ne coûte presque rien. Avec des milliers de riverains ou une pollution diffuse, les coûts de transaction rendent l’accord impossible, et l’on revient à la taxe, à la norme ou au marché de permis.") },

  /* ----- Niveau 3 ----- */
  { id: "et3-lindahl", theme: "etat", niveau: 3, type: "calcul", notion: "bien-public",
    titre: "Quelle quantité de bien public ?", competence: "Appliquer la condition de Samuelson et calculer des prix de Lindahl.",
    gen: () => { const [a, c] = pick([[[10, 8, 6], 9], [[14, 9, 7], 12], [[14, 10, 7], 13], [[12, 10, 8], 9], [[13, 10, 7], 12]]); return { a, c, Q: (a[0] + a[1] + a[2] - c) / 3 }; },
    enonce: (p) => P(`Trois ménages profitent d’un éclairage public dont la quantité Q peut varier. Leurs dispositions marginales à payer sont <b>${p.a[0]} − Q</b>, <b>${p.a[1]} − Q</b> et <b>${p.a[2]} − Q</b> francs. Chaque unité d’éclairage coûte <b>${p.c} francs</b>.`, "Calculez la quantité optimale, la quantité que le premier ménage achèterait s’il était seul à payer, puis le prix par unité que ce ménage devrait payer pour que chacun contribue à hauteur de sa disposition marginale à payer (prix de Lindahl)."),
    champs: [{ label: "Quantité optimale", unite: "", tol: 0.05 }, { label: "Quantité si le ménage 1 paie seul", unite: "", tol: 0.05 }, { label: "Prix de Lindahl du ménage 1", unite: "fr.", tol: 0.05 }],
    reponses: (p) => [p.Q, p.a[0] - p.c, p.a[0] - p.Q],
    indice: "Un bien public profite à tous en même temps. On additionne donc les dispositions marginales à payer avant de les comparer au coût marginal.",
    correction: (p) => { const S = p.a[0] + p.a[1] + p.a[2]; return P(`Somme des dispositions marginales à payer : (${p.a[0]} − Q) + (${p.a[1]} − Q) + (${p.a[2]} − Q) = ${S} − 3Q.`, `Condition de Samuelson : ${S} − 3Q = ${p.c}, donc Q = <b>${p.Q}</b>.`, `Seul, le ménage 1 achèterait jusqu’à ce que ${p.a[0]} − Q = ${p.c}, soit Q = <b>${p.a[0] - p.c}</b>. Les deux autres en profiteraient sans payer.`, `Pour obtenir le prix de Lindahl, chaque ménage paie sa disposition marginale à payer pour la quantité optimale, soit ${p.a[0]} − ${p.Q} = <b>${p.a[0] - p.Q} francs</b> pour le ménage 1, ${p.a[1] - p.Q} et ${p.a[2] - p.Q} francs pour les deux autres. Le total fait bien ${p.c} francs.`, "Le marché fournit trop peu de bien public, parce que chacun compte sur les autres. Les prix de Lindahl résoudraient le problème, mais ils supposent que chacun révèle sincèrement ce que le bien vaut pour lui. Or chacun a intérêt à le minimiser. C’est pourquoi le financement passe en pratique par l’impôt, et pourquoi l’école des choix publics, avec James Buchanan, s’interroge sur la capacité du vote à révéler ces préférences."); } },

  { id: "et3-van-publique", theme: "etat", niveau: 3, type: "calcul",
    titre: "Le taux d’actualisation d’un investissement public", competence: "Calculer une valeur actuelle nette et mesurer sa sensibilité au taux d’actualisation.",
    gen: () => ({ I: pick([80, 100, 120]), B: pick([4, 5, 6]), n: pick([30, 40]) }),
    enonce: (p) => P(`Une digue coûte <b>${p.I} millions de francs</b> aujourd’hui. Elle évite ensuite des dommages estimés à <b>${p.B} millions</b> par an pendant <b>${p.n} ans</b>.`, "Calculez la valeur actuelle nette du projet avec un taux d’actualisation de <b>1,4 %</b>, celui du rapport Stern sur le climat (2006), puis avec un taux de <b>4 %</b>, proche du rendement du capital privé. La valeur actuelle d’un montant annuel constant B versé pendant n années est B × (1 − (1 + r)<sup>−n</sup>) ÷ r. Arrondissez à une décimale et indiquez un signe moins si la valeur est négative."),
    champs: [{ label: "Valeur actuelle nette à 1,4 %", unite: "millions", tol: 0.1 }, { label: "Valeur actuelle nette à 4 %", unite: "millions", tol: 0.1 }],
    reponses: (p) => { const v = (r) => Math.round((p.B * (1 - Math.pow(1 + r, -p.n)) / r - p.I) * 10) / 10; return [v(0.014), v(0.04)]; },
    indice: "Calculez d’abord le facteur (1 − (1 + r)⁻ⁿ) ÷ r pour chaque taux, multipliez-le par le bénéfice annuel, puis retranchez le coût.",
    correction: (p) => { const f = (r) => (1 - Math.pow(1 + r, -p.n)) / r, f1 = f(0.014), f2 = f(0.04); return P(`À 1,4 % : facteur = (1 − 1,014<sup>−${p.n}</sup>) ÷ 0,014 ≈ ${fmt(f1, 3)}. Valeur actuelle des bénéfices = ${p.B} × ${fmt(f1, 3)} ≈ ${fmt(p.B * f1, 1)} millions.`, `Valeur actuelle nette = ${fmt(p.B * f1, 1)} − ${p.I} ≈ <b>${fmt(p.B * f1 - p.I, 1)} millions</b>.`, `À 4 % : facteur ≈ ${fmt(f2, 3)}, bénéfices ≈ ${fmt(p.B * f2, 1)} millions, valeur actuelle nette ≈ <b>${fmt(p.B * f2 - p.I, 1)} millions</b>.`, "L’écart entre les deux valeurs montre le poids du taux retenu, qui peut suffire à faire passer un projet de rentable à non rentable. Plus le taux est élevé, moins les bénéfices lointains comptent.", "Ce choix est au cœur du débat sur le climat. Nicholas Stern retient un taux bas, parce qu’il refuse de donner moins de poids au bien-être des générations futures. William Nordhaus défend un taux proche de celui qu’on observe sur les marchés, au motif que l’argent investi ailleurs rapporterait ce rendement et que les générations futures seront plus riches. Le calcul ne tranche pas. Il rend visible un jugement de valeur."); } },

  { id: "et3-graph-eviction", theme: "etat", niveau: 3, type: "graphique", notion: "multiplicateur",
    titre: "Relance budgétaire et effet d’éviction", competence: "Lire dans le modèle IS-LM l’effet d’une hausse des dépenses publiques.",
    enonce: P("Le graphique représente le modèle IS-LM. Une hausse des dépenses publiques déplace la courbe IS vers la droite, de IS à IS′. Si le taux d’intérêt restait inchangé, le revenu passerait de 50 à 70 (point K).", "Quelle lecture est correcte ?"),
    fig: () => X.graphe({ xmax: 112, ymax: 104, ylab: "Taux d’intérêt", xlab: "Revenu", aria: "Modèle IS-LM : la courbe IS se déplace vers la droite, le revenu et le taux d’intérêt augmentent",
      gx: [[50, "50"], [60, "60"], [70, "70"]], reperes: [[50, 50], [60, 60], [70, 50]],
      lignes: [{ pts: [[20, 80], [80, 20]], col: "d", lab: "IS", at: [80, 20], dx: 4, dy: 16, anc: "end" }, { pts: [[40, 80], [100, 20]], col: "d", dash: true, lab: "IS′", at: [100, 20], dx: 6, dy: 4 }, { pts: [[20, 20], [92, 92]], col: "o", lab: "LM", at: [92, 92], dx: 6, dy: 4 }],
      points: [{ x: 50, y: 50, lab: "E", dx: -16, dy: 6, anc: "end" }, { x: 60, y: 60, lab: "E′", col: "r", dx: -6, dy: -12, anc: "end" }, { x: 70, y: 50, lab: "K", col: "g", dx: 8, dy: -9 }],
      caption: "L’équilibre passe de E à E′." }),
    options: ["Le revenu passe de 50 à 60 et non à 70, car la hausse du taux d’intérêt réduit une partie de l’investissement privé.", "Le revenu passe de 50 à 70, car le taux d’intérêt ne dépend que de la banque centrale et reste inchangé.", "Le revenu reste à 50, car la hausse du taux d’intérêt annule entièrement l’effet de la dépense publique.", "Le revenu passe de 50 à 60, et le taux d’intérêt baisse, ce qui renforce l’effet de la relance."], c: 0,
    pourquoi: [null, "Le point K supposerait un taux inchangé. Or un revenu plus élevé augmente la demande de monnaie. Avec une offre de monnaie donnée, le taux monte le long de LM, jusqu’en E′.", "L’annulation complète supposerait une courbe LM verticale. Ici LM est croissante, et le revenu augmente de 10.", "Le nouvel équilibre E′ est plus haut que E. Le taux d’intérêt monte de 50 à 60 sur le graphique, il ne baisse pas."],
    explication: P("À taux inchangé, le multiplicateur porterait le revenu à 70. Mais la hausse du revenu accroît la demande de monnaie, ce qui fait monter le taux d’intérêt. L’investissement privé recule, et le revenu ne s’établit qu’à <b>60</b>. C’est l’<b>effet d’éviction</b>, ici partiel.", "Son ampleur dépend de la pente de LM. Si la demande de monnaie réagit beaucoup au taux, LM est presque horizontale et l’éviction est faible. C’est le cas de la trappe à liquidité, cher aux keynésiens. Si elle n’y réagit pas, LM est verticale et l’éviction est totale, comme le soutenaient les monétaristes.", "La banque centrale peut aussi accompagner la relance en augmentant l’offre de monnaie, ce qui déplace LM vers la droite et supprime l’éviction. Les nouveaux classiques ajoutent une objection d’une autre nature. Si les ménages anticipent les impôts futurs, ils épargnent davantage et la relance perd son effet (équivalence ricardienne de Robert Barro).") },

  { id: "et3-red-dette", theme: "etat", niveau: 3, type: "redaction", notion: "equivalence-ricardienne",
    titre: "La dette publique est-elle un fardeau pour les générations futures ?", competence: "Comparer plusieurs analyses de la dette publique et en tirer une position argumentée.",
    enonce: P("La dette publique dépasse 100 % du PIB aux États-Unis, en France ou en Italie, et reste inférieure à 40 % en Suisse, où le frein à l’endettement limite les déficits depuis 2003. Les économistes ne s’accordent pas sur le coût d’une dette élevée.", "<b>Consigne :</b> comparez au moins trois analyses de la dette publique en les rattachant à leurs auteurs (équivalence ricardienne de Barro ; Keynes et la finance fonctionnelle de Lerner ; Buchanan et l’école des choix publics ; Blanchard sur l’écart entre taux d’intérêt et croissance ; Kelton et la théorie monétaire moderne). Pour chacune, dites qui supporte la dette, à quelle condition elle pose problème et quelle règle budgétaire elle inspire. Appuyez-vous sur au moins un fait, puis prenez position. Longueur attendue, 20 à 30 lignes."),
    criteres: ["La réponse présente au moins trois analyses et nomme leurs auteurs.", "Elle dit pour chacune qui supporte la dette (contribuables futurs, personne si elle finance une production nouvelle, générations qui héritent de moins de capital).", "Elle précise à quelle condition la dette pose problème (taux d’intérêt supérieur à la croissance, plein emploi, inflation, dette en monnaie étrangère).", "Elle associe à chaque analyse une règle budgétaire (équilibre strict, équilibre sur le cycle, déficit réglé sur l’emploi et l’inflation).", "Elle cite au moins un fait et se termine par une prise de position explicite, justifiée par un des arguments présentés."],
    corrige: P("<b>Barro.</b> Selon l’équivalence ricardienne, des ménages prévoyants savent qu’une dette d’aujourd’hui signifie des impôts demain. Ils épargnent davantage et lèguent de quoi les payer. Financer une dépense par l’emprunt ou par l’impôt revient alors au même, et la dette n’est ni un fardeau ni un stimulant. L’hypothèse est forte, car elle suppose des ménages sans contrainte de crédit et soucieux de leurs descendants. Elle ne justifie donc aucune règle contre la dette, seul le niveau des dépenses publiques compte.", "<b>Keynes et Lerner.</b> En sous-emploi, un déficit met au travail des ressources inemployées. La dette détenue par les résidents est une créance des uns sur les autres, et non un appauvrissement du pays. Pour Abba Lerner, le budget doit viser le plein emploi sans inflation, pas l’équilibre. La dette ne pose problème qu’au plein emploi, où la dépense publique évince l’investissement privé.", "<b>Buchanan.</b> Les élus préfèrent dépenser qu’imposer, et les générations futures ne votent pas. Sans règle, la démocratie produit des déficits permanents, dont le coût est reporté. D’où la défense de règles constitutionnelles d’équilibre, dont le frein à l’endettement suisse est un exemple assoupli, puisqu’il raisonne sur l’ensemble du cycle.", "<b>Blanchard.</b> Tout dépend de l’écart entre le taux d’intérêt et le taux de croissance. Quand le premier est inférieur au second, la dette recule d’elle-même en proportion du PIB, et son coût est faible. Quand l’écart s’inverse, elle pèse sur les contribuables futurs. La règle qui en découle est de juger la soutenabilité par cet écart plutôt que par un plafond fixe. C’était le cas dans les pays avancés de 2010 à 2021. La remontée des taux depuis 2022 a rappelé que cette condition n’est pas garantie.", "<b>Kelton.</b> Un État qui emprunte dans sa propre monnaie ne peut pas faire défaut malgré lui. La vraie limite est l’inflation, dont les détenteurs de monnaie font les frais si elle s’emballe. Le déficit doit donc être réglé sur l’emploi et l’inflation, non sur un équilibre comptable. L’objection est que cette marge dépend de la confiance dans la monnaie et n’existe ni pour un pays endetté en devises ni pour un membre de la zone euro.", "<b>Prise de position possible.</b> La dette n’est pas un fardeau en soi. Elle l’est quand elle finance des dépenses courantes au plein emploi et quand le taux d’intérêt dépasse la croissance. Une règle qui équilibre le budget sur le cycle tout en protégeant l’investissement public paraît le meilleur compromis entre le risque politique décrit par Buchanan et le coût d’une austérité en récession.") },
]);
  /* =========================== FIN DES COMPLÉMENTS =========================== */
})();
